"Расстояние 200 м, скорость сближения 50 м/мин — догонит через 5 минут.": "Entfernung 200 m, Annäherungsgeschwindigkeit 50 m/min — er holt in 5 Minuten ein.",
"Вопрос не высказывание: про него нельзя сказать «истинно» или «ложно».": "Eine Frage ist keine Aussage: Man kann nicht sagen, sie sei „wahr“ oder „falsch“.",
