"Сумма скоростей — это движение навстречу. При движении вдогонку: v₁ − v₂.": "Die Summe der Geschwindigkeiten gilt bei der Bewegung entgegen. Bei der Bewegung hinterher: v₁ − v₂.",
"Айгерим — плавание. Динара не на танцы и не на плавание, значит, шахматы.": "Aigerim — Schwimmen. Dinara ist nicht beim Tanzen und nicht beim Schwimmen, also beim Schach.",
