"Чтобы найти, на сколько один урожай больше другого, надо оба урожая сложить.": "Um herauszufinden, um wie viel eine Ernte größer ist als die andere, muss man beide Ernten addieren.",
"Горизонтальных палочек (3 + 1) · 3 = 12 и столько же вертикальных. Всего 24.": "Waagerechte Stäbchen (3 + 1) · 3 = 12 und genauso viele senkrechte. Insgesamt 24.",
