"Если линия графика начинается не в нуле по времени, то движение начали позже.": "Wenn die Linie des Diagramms bei der Zeit nicht bei null beginnt, wurde die Bewegung später begonnen.",
"Знаменатель показывает, на какие доли разделили целое. Доли остаются теми же.": "Der Nenner zeigt, in welche Teile das Ganze geteilt wurde. Die Teile bleiben dieselben.",
